// Issue #43: the pay button can be pressed twice before the first charge comes back.
test('a second call while the first is still running does not charge again', async () => {
  const gateway = createSandboxGateway();
  const capture = createCapture(gateway);
  const order = { id: 'o-3', total: 1500 };
  const [first, second] = await Promise.all([capture(order), capture(order)]);
  assert.equal(gateway.charges.length, 1);
  assert.equal(second, first);
  assert.equal(order.receipt, first);
});

test('orders running at the same time are each charged once', async () => {
  const gateway = createSandboxGateway();
  const capture = createCapture(gateway);
  const a = { id: 'o-4', total: 100 };
  const b = { id: 'o-5', total: 200 };
  const [ra, rb] = await Promise.all([capture(a), capture(b), capture(a)]);
  assert.equal(gateway.charges.length, 2);
  assert.equal(ra.orderId, 'o-4');
  assert.equal(rb.orderId, 'o-5');
});

test('a failed charge can be tried again', async () => {
  let calls = 0;
  const gateway = {
    async charge(orderId, amount) {
      calls += 1;
      if (calls === 1) throw new Error('gateway down');
      return { id: 'ch_1', orderId, amount };
    },
  };
  const capture = createCapture(gateway);
  const order = { id: 'o-6', total: 300 };
  await assert.rejects(capture(order), /gateway down/);
  assert.notEqual(order.paid, true);
  const receipt = await capture(order);
  assert.equal(receipt.id, 'ch_1');
  assert.equal(calls, 2);
});
EOF
